const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const santaMonicaCoast = ee.Geometry.Point([-118.55, 34.0]); // A point off the coast of Santa Monica
  const startDate = '2015-10-01';
  const endDate = '2015-10-20'; // Widen the date window to find an image

  // Function to mask clouds for Landsat 8 Surface Reflectance data
  // Using 'pixel_qa' band for cloud, shadow, and water masking
  function maskL8sr(image) {
    // Bits 3 and 5 are cloud shadow and clouds, respectively.
    var cloudShadowBitMask = (1 << 3);
    var cloudsBitMask = (1 << 5);
    // Bit 2 is Dilated Cloud. Bit 4 is Snow/Ice.
    var dilatedCloudBitMask = (1 << 2);
    var snowIceBitMask = (1 << 4);

    // Get the QA band.
    var qa = image.select('pixel_qa');

    // Both flags should be set to zero, indicating clear conditions.
    var mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
      .and(qa.bitwiseAnd(cloudsBitMask).eq(0))
      .and(qa.bitwiseAnd(dilatedCloudBitMask).eq(0))
      .and(qa.bitwiseAnd(snowIceBitMask).eq(0));

    // Also mask out water pixels as algae bloom is an anomaly *in* water.
    // Bit 7 is water.
    var waterBitMask = (1 << 7);
    var waterMask = qa.bitwiseAnd(waterBitMask).eq(0); // Select pixels *not* water

    return image.updateMask(mask.and(waterMask))
      .select(['B2', 'B3', 'B4', 'B5', 'B6', 'B7'])
      .divide(10000); // Scale reflectance to 0-1
  }

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('LANDSAT/LC08/C01/T1_SR')
    .filterBounds(santaMonicaCoast)
    .filterDate(startDate, endDate)
    .map(maskL8sr)
    .sort('system:time_start', true); // Sort to get the closest image to Oct 10th

  const collectionSize = await collection.size().getInfo();

  if (collectionSize === 0) {
    console.log("No Landsat 8 images found for the specified date range and location after initial cloud/water masking.");
    console.log("C1");
    return;
  }

  // Get the image closest to October 10, 2015.
  // Since we sorted by time, the first image is the earliest in the window.
  // For a bloom on Oct 10, we'll take the closest one, let's just pick the first one (earliest) or the middle one.
  // For simplicity, let's take the first image if multiple are available.
  const image = ee.Image(collection.first());
  const imageDate = ee.Date(image.get('system:time_start')).format('YYYY-MM-dd').getInfo();

  // 3. Processing: Calculate a proxy for algae bloom and check pixel count
  // Algae blooms often cause an increase in green reflectance (Landsat B3).
  // We'll calculate a simple green index: B3 reflectance.
  // Let's also calculate EVI (Enhanced Vegetation Index) or NDVI for water.
  // For water, EVI can be more sensitive than NDVI to chlorophyll.
  // EVI = 2.5 * ((NIR - RED) / (NIR + 6 * RED - 7.5 * BLUE + 1))
  // For Landsat 8, NIR=B5, RED=B4, BLUE=B2
  const evi = image.expression(
    '2.5 * ((NIR - RED) / (NIR + 6 * RED - 7.5 * BLUE + 1))', {
      'NIR': image.select('B5'),
      'RED': image.select('B4'),
      'BLUE': image.select('B2')
    });

  // Green band reflectance (B3) is also a direct indicator for visible green blooms.
  const greenBand = image.select('B3');

  // Define a larger sampling region around Santa Monica to get context
  const samplingRegion = santaMonicaCoast.buffer(50000); // 50 km radius to get surrounding ocean

  // Check valid pixels in the broader region
  const bandToCount = 'B3'; // Use B3 as a representative band
  const countRegion = image.select(bandToCount).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: samplingRegion,
    scale: 300, // Landsat resolution
    maxPixels: 1e9
  });
  const pixelCount = await countRegion.get(bandToCount).getInfo();

  if (pixelCount === 0) {
    console.log(`Image date: ${imageDate}`);
    console.log("No valid pixels remain after cloud/water masking in the sampling region.");
    console.log("C2");
    return;
  }

  // 4. Calculation: Average EVI and Green band reflectance in the defined point.
  const roiRadius = 1000; // 1 km radius around the point
  const roi = santaMonicaCoast.buffer(roiRadius);

  const statsEVI = evi.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi,
    scale: 30, // Landsat resolution
    maxPixels: 1e9
  });
  const meanEVI = await statsEVI.get('constant').getInfo(); // EVI is a single band, named 'constant'

  const statsGreen = greenBand.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi,
    scale: 30,
    maxPixels: 1e9
  });
  const meanGreen = await statsGreen.get('B3').getInfo();

  // 5. Validation & Final Answer
  if (meanEVI === null || meanGreen === null || isNaN(meanEVI) || isNaN(meanGreen)) {
    console.log("Calculation resulted in Null or NaN for EVI or Green band reflectance.");
    console.log("C3");
    return;
  }

  // Typical EVI for clear ocean water is close to 0 or negative.
  // Typical Green (B3) reflectance for clear ocean is very low (e.g., < 0.02).
  // An algae bloom would likely show a higher EVI and significantly higher green reflectance.
  // A visible bloom could push EVI > 0.1 and Green reflectance > 0.05. These are indicative thresholds.
  const eviThreshold = 0.1;
  const greenThreshold = 0.05;

  const isAlgaeBloom = meanEVI > eviThreshold && meanGreen > greenThreshold;

  console.log(`Image found for: ${imageDate} (closest to Oct 10, 2015)`);
  console.log(`Mean EVI in ROI: ${meanEVI !== null ? meanEVI.toFixed(4) : 'N/A'}`);
  console.log(`Mean Green (B3) Reflectance in ROI: ${meanGreen !== null ? meanGreen.toFixed(4) : 'N/A'}`);
  console.log(`Valid pixels in broader region: ${pixelCount}`);

  if (isAlgaeBloom) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
